    /// With `fails` the file lies in a folder that is not there.
    let exportChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.reelsmith.EngineApi.export\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      exportChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let projectArg = args[0] as! String
        let settingsArg = args[1] as! String
        let mediaFolderArg = args[2] as! String
        let failsArg = args[3] as! Bool
        Task { @MainActor in
          do {
            let result = try await api.export(project: projectArg, settings: settingsArg, mediaFolder: mediaFolderArg, fails: failsArg)
            reply(wrapResult(result))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      exportChannel.setMessageHandler(nil)
    }
    /// Adds the file to Photos with the right to add only, then removes the file.
    let saveToPhotosChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.reelsmith.EngineApi.saveToPhotos\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      saveToPhotosChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let fileArg = args[0] as! String
        Task { @MainActor in
          do {
            let result = try await api.saveToPhotos(file: fileArg)
            reply(wrapResult(result))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      saveToPhotosChannel.setMessageHandler(nil)
    }
    /// Writes the cover of the project to the file.
    let writeCoverChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.reelsmith.EngineApi.writeCover\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      writeCoverChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let projectArg = args[0] as! String
        let mediaFolderArg = args[1] as! String
        let fileArg = args[2] as! String
        Task { @MainActor in
          do {
            try await api.writeCover(project: projectArg, mediaFolder: mediaFolderArg, file: fileArg)
            reply(wrapResult(nil))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      writeCoverChannel.setMessageHandler(nil)
    }
    /// The PNG bytes of the frames of a media for the blocks of the strip, by their time.
    let blockFramesChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.reelsmith.EngineApi.blockFrames\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      blockFramesChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let mediaArg = args[0] as! String
        let mediaFolderArg = args[1] as! String
        Task { @MainActor in
          do {
            let result = try await api.blockFrames(media: mediaArg, mediaFolder: mediaFolderArg)
            reply(wrapResult(result))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      blockFramesChannel.setMessageHandler(nil)
    }
    /// The screen stays awake while true.
    let keepAwakeChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.reelsmith.EngineApi.keepAwake\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      keepAwakeChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let awakeArg = args[0] as! Bool
        do {
          try api.keepAwake(awake: awakeArg)
          reply(wrapResult(nil))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      keepAwakeChannel.setMessageHandler(nil)
    }
    /// The PostScript names of the faces made for naskh and naskh bold, one space between them.
    let faceNamesChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.reelsmith.EngineApi.faceNames\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      faceNamesChannel.setMessageHandler { _, reply in
        do {
          let result = try api.faceNames()
          reply(wrapResult(result))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      faceNamesChannel.setMessageHandler(nil)
    }
    /// Shows the question as a system alert with a destructive button and a cancel button. True when she
    /// confirmed.
    /// Swift sets the identifiers `drafts.deleteConfirm` and `drafts.deleteCancel` on the two buttons.
    let confirmChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.reelsmith.EngineApi.confirm\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      confirmChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let questionArg = args[0] as! String
        let confirmWordsArg = args[1] as! String
        let cancelWordsArg = args[2] as! String
        Task { @MainActor in
          do {
            let result = try await api.confirm(question: questionArg, confirmWords: confirmWordsArg, cancelWords: cancelWordsArg)
            reply(wrapResult(result))
          } catch {
